SELECT A.YYMON YYYYMM, 'SA' IF_SYSTEM, #CD_COMPANY# CD_COMPANY, '3010' CD_EPCODE, '1000'CD_PC, '110020' CD_WDEPT, TO_CHAR(LAST_DAY(TO_DATE(A.YYMON, 'YYYYMM')), 'YYYYMMDD') DT_ACCT, '99' CD_EVID, TO_CHAR(LAST_DAY(TO_DATE(A.YYMON, 'YYYYMM')), 'YYYYMMDD') DT_START, '' DT_END, '매출원가' NM_NOTE, PRCHS_AMT AM_TAXSTD, 0 AM_ADDTAX, 'SE' CD_BIZAREA, CD.ERP_DEPT_CD CD_CC, CD.ERP_DEPT_CD CD_DEPT, '2179014' CD_EMPLOY, GETALANCINFO(CSTMR_ID, 'BIZMN_REGST_NO') CD_PARTNER, GETALANCINFO(CSTMR_ID, 'BIZMN_REGST_NO') NO_COMPANY, A.CSTMR_ID CD_UMNG1, 'A02' CD_MNG1, CD.ERP_DEPT_CD CD_MNGD1, CD.ALANC_DEPT_NM NM_MNGD1, 'A06' CD_MNG2, GETALANCINFO(CSTMR_ID, 'BIZMN_REGST_NO') CD_MNGD2, GETALANCINFO(CSTMR_ID, 'ALANC_NM') NM_MNGD2, 'B22' CD_MNG3, '' CD_MNGD3, ''NM_MNGD3, 'C44' CD_MNG4, '' CD_MNGD4, '' NM_MNGD4, 'C16' CD_MNG5, '' CD_MNGD5, '' NM_MNGD5, 'B24' CD_MNG6, '' CD_MNGD6, '' NM_MNGD6, 'B25' CD_MNG7, '' CD_MNGD7, '' NM_MNGD7, 'B26' CD_MNG8, '' CD_MNGD8, ''NM_MNGD8, 'K02' CD_MNG9, '' CD_MNGD9, ' ' NM_MNGD9, 'K10' CD_MNG10, 'SA' CD_MNGD10, '건설' NM_MNGD10, '000' CD_EXCH, '' RT_EXCH, '' AM_EX, '' ST_MUTUAL, '' NO_TO, '' DT_SHIPPING, '0' TP_EVIDENCE FROM ( SELECT CSTMR_ID , YYMON , SUM(SLS) SLS_AMT , SUM(PRCHS) PRCHS_AMT FROM (SELECT CSTMR_ID, CLSN_YYMON YYMON, SLS_AMT SLS, 0 PRCHS FROM KEPMPCL02 WHERE CLSN_YYMON = (SELECT KEY_1 FROM ICOMTRXL WHERE DOC_NAME = 'SALE_COST' AND TARGET = 'SA' AND KEY_9 = ' ') AND BIZ_CLSS_CD = 'C001' AND SLS_CNFRM_CHK = 'Y' AND USE_CHK = 'Y' UNION ALL SELECT CSTMR_ID, ACCNT_YYMON YYMON, 0 SLS, DLVRY_AMT PRCHS FROM KEPCMRP05 WHERE ACCNT_YYMON = (SELECT KEY_1 FROM ICOMTRXL WHERE DOC_NAME = 'SALE_COST' AND TARGET = 'SA' AND KEY_9 = ' ') AND BIZ_CLSS_CD = 'C001') A GROUP BY A.CSTMR_ID, A.YYMON
HAVING SUM(A.SLS) > 0 OR SUM(A.PRCHS) > 0
) A , KEPCODP01 CD WHERE CD.ALANC_DEPT_CD = '010' AND CD.ALANC_ID = 'KRKORE0001' ORDER BY CD_PARTNER

